CREATE TYPE "ProfileType" AS ENUM ('STUDENT','WORKING_PROFESSIONAL','OTHER');
CREATE TYPE "LeagueStatus" AS ENUM ('SCHEDULED','OPEN','CLOSED');
ALTER TABLE "User" ADD COLUMN "profileType" "ProfileType" NOT NULL DEFAULT 'STUDENT', ADD COLUMN "profession" VARCHAR(150), ADD COLUMN "educationStage" VARCHAR(30), ADD COLUMN "schoolClass" VARCHAR(50), ADD COLUMN "fieldOfStudy" VARCHAR(100);
CREATE TABLE "AuthSession"("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID NOT NULL,"tokenHash" VARCHAR(128) NOT NULL UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastActivityAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AuthSession_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "AuthSession_userId_expiresAt_idx" ON "AuthSession"("userId","expiresAt");
CREATE TABLE "LeagueCycle"("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"name" VARCHAR(100) NOT NULL,"status" "LeagueStatus" NOT NULL DEFAULT 'SCHEDULED',"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"winnerUserId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "LeagueCycle_status_startsAt_endsAt_idx" ON "LeagueCycle"("status","startsAt","endsAt");
CREATE TABLE "LeagueParticipant"("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"cycleId" UUID NOT NULL,"userId" UUID NOT NULL,"kp" INTEGER NOT NULL DEFAULT 0,"streakDays" INTEGER NOT NULL DEFAULT 0,"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "LeagueParticipant_cycleId_fkey" FOREIGN KEY("cycleId") REFERENCES "LeagueCycle"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "LeagueParticipant_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "LeagueParticipant_cycleId_userId_key" UNIQUE("cycleId","userId"));
CREATE INDEX "LeagueParticipant_cycleId_kp_idx" ON "LeagueParticipant"("cycleId","kp");
CREATE TABLE "DailyQuote"("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"dateKey" VARCHAR(10) NOT NULL UNIQUE,"quote" TEXT NOT NULL,"source" VARCHAR(150) NOT NULL,"category" VARCHAR(60) NOT NULL);
CREATE TABLE "DailyDirective"("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"title" VARCHAR(160) NOT NULL,"description" TEXT NOT NULL,"rewardXp" INTEGER NOT NULL DEFAULT 0,"rewardCoins" INTEGER NOT NULL DEFAULT 0,"ordering" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE "DirectiveClaim"("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"directiveId" UUID NOT NULL,"userId" UUID NOT NULL,"claimDate" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DirectiveClaim_directiveId_fkey" FOREIGN KEY("directiveId") REFERENCES "DailyDirective"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "DirectiveClaim_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "DirectiveClaim_directiveId_userId_claimDate_key" UNIQUE("directiveId","userId","claimDate"));
CREATE INDEX "DirectiveClaim_userId_claimDate_idx" ON "DirectiveClaim"("userId","claimDate");